// src/dvs2/message-references.ts
function readMessageReferences(chat) {
  const references = [];
  for (const message of chat) {
    if (message.is_user)
      continue;
    for (let i = 0;i < (message.swipes?.length ?? 1); i++) {
      const fid = message.variables?.[i]?.dvs?.fid;
      if (typeof fid === "string")
        references.push(fid);
    }
  }
  return references;
}

