    store.validateAction(action);
    const fixedAction = structuredClone(action);
    if (!config.apiUrl)
      throw new Error("请填写 API 基础地址。");
    await copiedKeys.get(action)?.();
    const fixed = await store.capture(configId);
    const key = fixedAction.kind === "replace" ? fixedAction.value : fixedAction.kind === "clear" ? "" : configId === undefined ? "" : await fixed.read();
