      if (!selected)
        throw new Error("模型配置不存在，请重新读取列表。");
      const fixed = await store.capture(id);
      const key = await fixed.read();
      await fixed.checkCurrent();
      const action = key ? { kind: "replace", value: key } : { kind: "clear" };
      copiedKeys.set(action, fixed.checkCurrent);
