  const file = event.fileState === "saved" ? "文件已写入，但后续登记或文件信息读取失败。" : event.fileState === "unknown" ? "无法确认文件是否完整写入。" : "本次后台保存没有写入文件。";
  const memory = event.memoryAvailable ? "修改仍在当前内存中；关闭、切换或重载可能丢失尚未保存的修改。" : "当前数据库实例无法继续使用，请检查文件及备份。";
