        const original = errorData(error);
        const startupError = stage === "settings" ? original : {
          ...original,
          message: "SQLite 服务启动失败。请在扩展设置中查看详情，处理后刷新页面。",
          causeError: original.causeError ?? detail(error),
          resultState: "not-applied"
        };
