// src/tavern/scan-repair-execution.ts
function updateLaterExpectations(result, laterSteps) {
  if (!result.registrationChanged)
    return;
  for (const later of laterSteps) {
    if (later.kind !== "repair")
      continue;
    if (result.role && later.request.avatar === result.role.avatar)
      later.request.expectedRole = result.role;
    if (result.target && later.request.scope === result.target.scope && later.request.charDbId === result.target.charDbId && (later.request.scope === "chat" ? later.request.chatDbId : undefined) === result.target.chatDbId) {
      later.request.expectedTarget = result.target;
      if (later.request.scope === "chat" && later.request.expectedChat)
        later.request.expectedChat = { ...later.request.expectedChat, initialization: result.target.state };
    }
  }
}
async function executeScanRepair(input) {
  const { step, binding, client } = input;
  let chatConfirmed = false;
  try {
    const checked = await client.repairScan({ ...step.request, phase: "check" }, binding);
    if (checked.status !== "checked")
      return { status: "failed", message: checked.message };
    if (step.request.scope === "chat") {
      if (!step.expectedRaw)
        return { status: "failed", message: "缺少扫描时的聊天状态，请重新扫描。" };
      await input.saveChatIdentity({
        avatar: step.request.avatar,
        file: step.request.file,
        desiredId: step.request.chatDbId,
        expectedRaw: step.expectedRaw,
        ...step.expectedLocalRaw ? { expectedLocalRaw: step.expectedLocalRaw } : {}
      });
      chatConfirmed = true;
    }
    const result = await client.repairScan({
      ...step.request,
      phase: "apply",
      ...step.request.scope === "chat" ? { confirmedChatId: step.request.chatDbId } : {}
    }, binding);
    if (result.status === "repaired" || result.status === "unchanged") {
      updateLaterExpectations(result, input.laterSteps);
      return { status: "done", message: "已恢复关联，原数据已保留。" };
    }
    return {
      status: chatConfirmed ? "partial" : "failed",
      message: `${chatConfirmed ? "聊天关联已保存，但登记尚未完成。" : ""}${result.message} 请重新扫描。`
    };
  } catch (error) {
    const detail = errorData(error);
    if (chatConfirmed)
      return {
        status: "partial",
        message: `聊天关联已保存，但登记结果尚未确认。请重新扫描。${detail.message}`
      };
    return {
      status: "failed",
      message: `${detail.resultState === "unconfirmed" ? "聊天关联保存结果未确认。" : "未完成："}${detail.message} 请重新扫描确认当前结果。`
    };
  }
}

// src/tavern/management-repair-readback.ts
async function readManagementRepairObservations(owner, coordinates, cancelled = () => false) {
  const readback = new TavernScanReadback(owner, undefined, cancelled);
  const observations = [];
  for (const record of coordinates) {
    if (cancelled())
      break;
    const observed = await readback.check({
      scope: record.scope,
      referenceId: record.referenceId,
      avatar: record.avatar,
      ...record.file === undefined ? {} : { file: record.file },
      id: isUuid(record.id) ? record.id : null,
      ...isUuid(record.parent) ? { parent: record.parent } : {},
      state: "active",
      taskReasons: [],
      parentDependency: false,
      shared: false
    });
    observations.push({
      scope: record.scope,
      referenceId: record.referenceId,
      avatar: record.avatar,
      ...record.file === undefined ? {} : { file: record.file },
      status: observed.identityStatus ? "same" : observed.status,
      observedId: observed.observedId ?? null,
      ...observed.status === "unknown" && !observed.identityStatus ? { reason: observed.reason } : {}
    });
  }
  return observations;
}

// src/tavern/database-maintenance-readback.ts
async function readDatabaseMaintenanceEvidence(owner, plan, client, binding, cancelled = () => false) {
  const observations = await readManagementRepairObservations(owner, plan.records.map((record) => ({
    scope: record.scope,
    referenceId: record.referenceId,
    avatar: record.avatar,
    file: record.file,
    id: record.id,
    parent: record.parent
  })), cancelled);
  if (plan.target.scope !== "global")
    return { observations };
  const inventory = await client.scan({ operation: "inventory" }, binding);
  const candidates = inventory.entries.flatMap((entry) => {
    const part = entry.kind === "file" && !entry.reason ? parseDatabasePath(entry.relativePath, "file") : undefined;
    return part?.kind === "chat" ? [{ parent: part.charDbId, chatId: part.chatDbId }] : [];
  });
  const discovery = await new TavernScanReadback(owner, undefined, cancelled).discover({
    candidates,
    roles: plan.records.filter((record) => record.scope === "char" && record.state !== "deleted").map((record) => ({ avatar: record.avatar, id: record.id }))
  });
  for (const match of discovery.matches) {
    const role = observations.find((observation) => observation.scope === "char" && observation.avatar === match.avatar);
    if (role?.status === "same")
      match.rolePresent = true;
    else if (role?.status === "deleted")
      match.rolePresent = false;
  }
  if (inventory.issues.length) {
    discovery.complete = false;
    discovery.issues.push(...inventory.issues.map((issue) => issue.reason));
  }
  return { observations, discovery };
}

// src/tavern/database-maintenance-execution.ts
async function executeDatabaseMaintenance(input) {
  if (input.preparedEvidence !== input.plan.evidence || input.plan.file === "present" && (!input.backupDigest || !input.backupConfirmed) || input.plan.loss.length && !input.lossConfirmed)
    throw new Error("请先准备原文件备份并确认本次影响，尚未开始处理。");
  return input.client.maintainDatabase({
    phase: "apply",
    expected: input.plan,
    ...await input.readEvidence(),
    ...input.backupDigest ? { backupDigest: input.backupDigest } : {}
  }, input.binding);
}

