// src/dvs2/request-errors.ts
var records = [];
var listeners = new Set;
var nextId = 0;
function notify() {
  for (const listener of listeners) {
    try {
      listener();
    } catch {}
  }
}
var dvsRequestErrors = {
  getRecords() {
    return structuredClone(records);
  },
  subscribe(listener) {
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  },
  clear() {
    records.length = 0;
    notify();
  }
};
function sanitized(value, key) {
  if (typeof value === "string") {
    if (!key)
      return value;
    return value.split(key).join("[密钥已隐藏]").split(JSON.stringify(key).slice(1, -1)).join("[密钥已隐藏]");
  }
  if (Array.isArray(value))
    return value.map((item) => sanitized(item, key));
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([name, item]) => {
      if (/^(authorization|proxy_password|api[_-]?key|password|secret|access_token|custom_include_headers)$/i.test(name))
        return [name, "[凭据已隐藏]"];
      if (name === "custom_include_body" && typeof item === "string") {
        try {
          return [name, JSON.stringify(sanitized(JSON.parse(item), key))];
        } catch {}
      }
      return [name, sanitized(item, key)];
    }));
  }
  return value;
}
function createRequestErrorCapture(snapshot, purpose, attempt, context) {
  const trace = { response: {} };
  let recorded = false;
  return {
    trace,
    record(error, stage) {
      if (recorded)
        return;
      try {
        const record = sanitized({
          id: ++nextId,
          time: new Date().toISOString(),
          purpose,
          attempt,
          stage,
          reason: error instanceof Error ? error.message : String(error),
          context,
          model: snapshot.config.model,
          apiUrl: snapshot.config.apiUrl,
          request: trace.request ?? null,
          response: trace.response
        }, snapshot.key);
        records.unshift(record);
        if (records.length > 30)
          records.length = 30;
        recorded = true;
        notify();
      } catch {}
    }
  };
}

