async function prepareModelRequest(input) {
  const snapshot = { ...input.snapshot, config: readModelConfig(input.snapshot.config) };
  const protocol = composeTaskProtocol(input.tasks);
  const prompt = {
    protocol,
    data: input.data,
    messages: input.messages,
    profile: promptProfile(input.stage, snapshot.config.model),
    outputFormat: snapshot.config.outputFormat
  };
  const messages = input.stage === "userReq" ? composeUserReqMessages(prompt) : composeAiReqMessages(prompt);
  return { tasks: input.tasks, messages, schema: protocol.schema, snapshot };
}
function parseModelResponse(raw, tasks) {
  const value = JSON.parse(raw.trim().replace(/^```(?:json)?\s*\n?([\s\S]*?)\n?```$/i, "$1"));
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("DVS 模型结果必须是 JSON 对象。");
  const data = {}, analyses = [];
  for (const key of Object.keys(tasks)) {
    const wrapped = value[key];
    if (!wrapped || typeof wrapped !== "object" || Array.isArray(wrapped) || !Object.hasOwn(wrapped, "data"))
      throw new Error(`DVS 模型结果缺少 ${key}.data。`);
    const entry = wrapped;
    data[key] = entry.data;
    if (typeof entry.cot === "string" && entry.cot.trim())
      analyses.push({ extensions: [key], content: entry.cot });
  }
  return { data, analyses };
}
function waitRetry(milliseconds, signal) {
  return new Promise((resolve, reject) => {
    if (signal.aborted) {
      reject(signal.reason);
      return;
    }
    const abort = () => {
      clearTimeout(timer);
      reject(signal.reason);
    };
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", abort);
      resolve();
    }, milliseconds);
    signal.addEventListener("abort", abort, { once: true });
  });
}

