// src/dvs2/adapter.ts
function createTavernAdapter(owner, prepareWorldbook) {
  const context = () => owner.SillyTavern.getContext();
  const avatar = () => {
    const ctx = context();
    if (ctx.groupId != null && ctx.groupId !== "")
      throw new Error("DVS 只支持单人角色聊天。");
    return ctx.characters[Number(ctx.characterId)]?.avatar;
  };
  const capture = (floorid, swipeid = context().chat[floorid]?.swipe_id ?? 0) => {
    const ctx = context(), chat = ctx.chat, message = chat[floorid], chatId = ctx.chatId, character = avatar();
    if (!character || !chatId || !message || !Number.isInteger(floorid) || !Number.isInteger(swipeid) || swipeid < 0 || swipeid >= (message.swipes?.length ?? 1))
      throw new Error("DVS 目标消息或回复版本不存在。");
    const displayed = message.swipe_id ?? 0;
    let chatDbId;
    const assertCurrent = () => {
      const next = context();
      if (avatar() !== character || next.chatId !== chatId || next.chat !== chat || chat[floorid] !== message || (message.swipe_id ?? 0) !== displayed)
        throw new Error("聊天或回复版本已经切换，请重新读取 DVS 状态。");
    };
    const row = () => {
      assertCurrent();
      return owner.TavernHelper.getChatMessages(String(floorid), { include_swipes: true })[0];
    };
    const body = () => {
      assertCurrent();
      return swipeid === displayed ? message.mes : message.swipes[swipeid];
    };
    const version = () => {
      const value = row()?.swipes_data[swipeid]?.dvs?.fid;
      if (value == null)
        return;
      if (typeof value !== "string" || !/^[a-f\d]{8}-(?:[a-f\d]{4}-){3}[a-f\d]{12}$/i.test(value))
        throw new Error("DVS 版本关联不是有效 UUID。");
      return value.toLowerCase();
    };
    const readServer = async () => {
      assertCurrent();
      const response = await (owner.fetch ?? fetch)("/api/chats/get", {
        method: "POST",
        headers: context().getRequestHeaders(),
        cache: "no-cache",
        body: JSON.stringify({
          avatar_url: character,
          file_name: chatId,
          ch_name: ctx.characters[Number(ctx.characterId)]?.name
        })
      });
      assertCurrent();
      if (!response.ok)
        throw new Error(`DVS 聊天保存未确认：读回 HTTP ${response.status}。`);
      const stored = await response.json();
      assertCurrent();
      if (!Array.isArray(stored) || !stored[floorid + 1] || typeof stored[floorid + 1] !== "object")
        throw new Error("DVS 聊天文件没有目标消息，保存未确认。");
      if (chatDbId && stored[0]?.chat_metadata?.st_sle_helper?.chat_dbid !== chatDbId)
        throw new Error("聊天文件的数据库编号与固定目标不一致，DVS 保存未确认。");
      return stored[floorid + 1];
    };
    const save = async (text, fid, changeVersion, refresh = "none") => {
      assertCurrent();
      if (!chatDbId)
        throw new Error("DVS 保存尚未绑定聊天数据库。");
      const data = row()?.swipes_data;
      if (!data || data.length !== (message.swipes?.length ?? 1))
        throw new Error("助手没有返回完整回复版本资料，未保存 DVS。");
      const variables = data.map((value) => ({ ...value }));
      if (changeVersion)
        variables[swipeid] = { ...variables[swipeid], dvs: { ...variables[swipeid]?.dvs, fid: fid ?? null } };
      const swipes = [...message.swipes ?? [message.mes]];
      swipes[displayed] = message.mes;
      swipes[swipeid] = text;
      await owner.TavernHelper.setChatMessages([{ message_id: floorid, swipes, swipes_data: variables }], {
        refresh
      });
      assertCurrent();
      await context().saveChat();
      assertCurrent();
      const saved = await readServer();
      const savedText = swipeid === (saved.swipe_id ?? 0) ? saved.mes : saved.swipes?.[swipeid];
      if (savedText !== text || changeVersion && (saved.variables?.[swipeid]?.dvs?.fid ?? undefined) !== fid)
        throw new Error("DVS 消息或版本关联与聊天文件读回不一致，请重新打开聊天核对。");
      if (!changeVersion)
        await owner.TavernHelper.refreshOneMessage?.(floorid);
    };
    return {
      floorid,
      swipeid,
      message,
      chatId,
      avatar: character,
      key: JSON.stringify([character, chatId, floorid, swipeid]),
      assertCurrent,
      body,
      version,
      readServer,
      bindDatabase(id) {
        if (chatDbId && chatDbId !== id)
          throw new Error("DVS 目标的聊天数据库编号已经改变。");
        chatDbId = id;
      },
      content: () => stripDvsCapsules(body()),
      capsule: (type) => readCapsule(body(), type)?.document,
      saveCapsule: (type, document2, summary = {}, refresh = "none", ensurePanel = false) => save(replaceCapsule(body(), type, document2, summary, ensurePanel), undefined, false, refresh),
      ensureCapsule: async (type) => {
        if (!/<(?:DVSData\b|DVSInputInject\b|DVSUpdateData\b)/i.test(body()))
          await save(replaceCapsule(body(), type, { records: {} }), undefined, false);
      },
      associateVersion: (fid) => save(body(), fid, true)
    };
  };
  const latest = (type, before = context().chat.length) => {
    const chat = context().chat;
    for (let id = before - 1;id >= 0; id--) {
      const row = chat[id];
      if (!row.is_system && row.extra?.type !== "narrator" && Boolean(row.is_user) === (type === "user"))
        return capture(id, Math.min(row.swipe_id ?? 0, (row.swipes?.length ?? 1) - 1));
    }
    return;
  };
  const worldbooks = {
    getCharWorldbookNames: (avatar) => owner.TavernHelper.getCharWorldbookNames(avatar),
    getWorldbook: (book) => owner.TavernHelper.getWorldbook(book),
    prepareWorldbook
  };
  const readReferences = () => readMessageReferences(context().chat);
  return {
    context,
    avatar,
    capture,
    latest,
    readReferences,
    helper: owner.TavernHelper,
    worldbooks,
    variableWorldbookScan: false
  };
}

