// src/dvs2/narrative-length.ts
function narrativeLength(body) {
  return stripDvsCapsules(body).replace(/<!--[\s\S]*?-->/g, "").replace(/<[^>]*>/g, "").length;
}

// src/dvs2/narrative-prompt.ts
function replaceNarrativeText(text, preparedSupplement, replace) {
  return preparedSupplement ? text.split(preparedSupplement).map(replace).join(preparedSupplement) : replace(text);
}

// src/dvs2/native.ts
async function loadNativeGenerationPort() {
  const nativeImport = (path) => import(path);
  const [script, world] = await Promise.all([nativeImport("/script.js"), nativeImport("/scripts/world-info.js")]);
  if (typeof script.setSendButtonState !== "function")
    throw new Error("当前酒馆缺少生成状态接口。");
  return {
    recursionLimit: () => Number(world.world_info_max_recursion_steps) || 0,
    setBusy: (value) => script.setSendButtonState(value),
    generate: () => script.Generate("regenerate", { automatic_trigger: true })
  };
}
