  const keep = () => {
    port.setBusy(true);
    context.deactivateSendButtons?.();
  };
  keep();
  const observer = new MutationObserver(() => {
    if (owner.document.body.dataset.generating !== "true")
      keep();
  });
  observer.observe(owner.document.body, { attributes: true, attributeFilter: ["data-generating"] });
  return () => {
    observer.disconnect();
    port.setBusy(false);
    context.activateSendButtons?.();
  };
