// src/dvs2/capsule-visibility.ts
async function ensureCapsuleVisibility() {
  const nativeImport = (path) => import(path);
  const [regex, script] = await Promise.all([
    nativeImport("/scripts/extensions/regex/engine.js"),
    nativeImport("/script.js")
  ]);
  if (typeof regex.getScriptsByType !== "function" || typeof regex.saveScriptsByType !== "function" || regex.SCRIPT_TYPES?.GLOBAL === undefined || typeof script.saveSettings !== "function")
    throw new Error("酒馆缺少新版 DVS 胶囊隐藏正则接口。");
  const common = {
    disabled: false,
    findRegex: "/<(DVSData|DVSInputInject|DVSUpdateData)\\b[^>]*>[\\s\\S]*?<\\/\\1>/gi",
    replaceString: "",
    trimStrings: [],
    placement: [1, 2],
    runOnEdit: true,
    substituteRegex: 0,
    minDepth: null,
    maxDepth: null
  };
  const expected = [
    {
      ...common,
      id: "sqlite-helper-dvs2-capsule-prompt",
      scriptName: "DVS：请求中隐藏胶囊",
      markdownOnly: false,
      promptOnly: true
    },
    {
      ...common,
      id: "sqlite-helper-dvs2-capsule-display",
      scriptName: "DVS：隐藏胶囊原文",
      markdownOnly: true,
      promptOnly: false
    },
    {
      ...common,
      id: "sqlite-helper-dvs-config-prompt",
      scriptName: "DVS：请求中隐藏配置标签",
      findRegex: "/<DVSConfig\\/>/g",
      placement: [2],
      replaceString: "",
      markdownOnly: false,
      promptOnly: true
    },
    {
      ...common,
      id: "sqlite-helper-dvs-config-display",
      scriptName: "DVS：显示开场白配置面板",
      findRegex: "/<DVSConfig\\/>/g",
      placement: [2],
      replaceString: '<span data-dvs-ui-slot="config"></span>',
      markdownOnly: true,
      promptOnly: false
    }
  ];
  const existing = regex.getScriptsByType(regex.SCRIPT_TYPES.GLOBAL);
  if (expected.every((rule) => existing.filter((value) => value.id === rule.id).length === 1 && existing.some((value) => Object.entries(rule).every(([key, field]) => JSON.stringify(value[key]) === JSON.stringify(field)))))
    return;
  await regex.saveScriptsByType([...existing.filter((rule) => !expected.some((value) => value.id === rule.id)), ...expected], regex.SCRIPT_TYPES.GLOBAL);
  await script.saveSettings();
}

